pub fn count_uppercase(text: &Vec<char>) -> u64 {
    // Total for all inputs (including empty); counts only ASCII 'A'..'Z'.
    text.iter()
        .filter(|&&c| matches!(c, 'A'..='Z'))
        .count() as u64
}